 examples=[
  X("FRY / MERY (misspellings)", "F = 6 (alphabet) and ME = 110 = 6 (binary), both + RY (43)", "'ME 43' = a typical Zodiac sentence. Penn gives ME 43 = 110101011 as 'base-ten 350'; the value is 427.", ('m','ME 43',427), err=True),
  X("THREE / BUS redivided", "10000010 | 00 = 130 + I", "'I (am) 130' (Mensa Bulletin 1985).", ('mb','THREE','1000001000')),
  X("MELVIN EATS BLUBER", "1100100 000100 100011 000100 0010 0001 10000010", "= hundred, S + crossed circle (100), 35, S + crossed circle, F, V, 130: 'GENE'S 100, BM'S 100, FV, BER' (the only Zodiac 'to be').", ('mb','MELVIN EATS BLUBER','11001000001001000110001000010000110000010')),
  X("NEAD (Pen Card)", "10 0 01 100 = 1000 11 00 = 'BM (am) I' = 140", "Misspelling read as a sentence.", ('rd','NEAD','BM I'), ('m','BM I',140)),
 ],
 claims="Penn claims the language is internally consistent and 'self-identifying'.",
 first_seen="1985 (Mensa Bulletin: 'ME 43')",
 citations=["Mensa Bulletin Jul/Aug 1985, p.6-7 (scans 3-4)", "T17:4", "T17:22", "T17:43", "T17:52", "T17:65", "T17:94", "T17:202", "T17:205", "T17:217", "T17:224"],
