dict(id="letter-containment", name="Letter containment (a Morse letter 'contains' a shorter one)", category="morse-binary",
 summary="Because some Morse letters are prefixes of others (I = 00 contains E = 0; G = 110 contains ME), one letter may stand in for another, and a word may be 'completed' by any letter ending in the right bit.",
 rules="Substitute a longer letter for a shorter one whose bits it contains (S = 000 for I = 00, I for E). A word may be completed by 'any letter ending in 0' or 'any base-two number' (which always begins with 1).",
 examples=[
  X("Lower-case g in MARgOULIES (O'Hare's marriage licence)", "G = 110 = ME (11 0)", "'ME in MARGOULIES' (handwriting exhibit).", ('rd','G','ME')),
  X("SHADTO", "S = 000 contains I = 00 -> I HAD TO", "SP p.49.", ('in','SHADTO','IHADTO')),
  X("Any letter ending in 0 + ATHER", "_0 + 010 ... = FATHER", "Penn's rule for completing family words.", ('mb','FATHER','001001100000010')),
  X("Feb 1974 acrostic DUALG", "G = 110 = redivision of ME -> DUAL ME", "17-column row initials of the SLA letter.", ('rd','G','ME')),
 ],
 claims="Penn claims these substitutions reveal hidden family words and O'Hare's 'dual' identity.",
 first_seen="1999 (The Second Power)",
 citations=["SP:19", "SP:28", "SP:34", "SP:38", "SP:40", "SP:44", "SP:49", "SP:56"],
 demo=D("redivision", "G", "ME"),
 related=["digital-redivision","embedded-redivision-search"]),

